#ifndef TLS_FILES_H_
#define TLS_FILES_H_

#include <stdint.h>

/*
 * Stage 2b support: the project CA certificate and the device clock.
 *
 * The CA certificate is compiled in (secrets.h, generated by
 * host/dt_setup_security.py) and copied to the network processor's file
 * system at boot, so there is no separate UniFlash step. The file is only
 * rewritten when its contents differ, which spares the flash.
 */

/* Returns 0 if the file already matched, 1 if it was written, negative on error. */
int32_t TlsFiles_installCa(const char *fileName, const char *pem, uint32_t len);

/*
 * The network processor checks certificate dates against its own clock,
 * which starts at an arbitrary value. This sets it to the firmware build
 * time, which is always after the certificates were generated (secrets.h is
 * compiled in), and well inside their validity period.
 */
void TlsFiles_setClockFromBuild(void);

#endif /* TLS_FILES_H_ */
